// A local track may have two images: the original cover (full resolution) and a
// small derived thumbnail generated by the desktop backend. Lists, grids and the
// compact player use `cover`, which decodes to ~1 MB instead of tens of MB;
// the bigscreen view asks for `fullCover`.
export function localCoverSources(
  scanned: { cover: string | null; thumbnail?: string | null },
  toSource: (path: string) => string,
  placeholder: string,
): { cover: string; fullCover: string | undefined } {
  const playable = (path: string) =>
    path.startsWith("data:") ? path : toSource(path);
  if (scanned.cover === null) return { cover: placeholder, fullCover: undefined };
  if (!scanned.thumbnail) {
    return { cover: playable(scanned.cover), fullCover: undefined };
  }
  return {
    cover: playable(scanned.thumbnail),
    fullCover: playable(scanned.cover),
  };
}
